def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    marker=5
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==marker]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b): out[r][c]=3
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==marker]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b): out[r][c]=3
    return out
